  if (ai.msg) n += 0.8 + Math.max(1, Math.ceil(String(ai.msg.text || '').length / per));
  (ai.prompt || []).forEach((r) => { n += Math.max(1, Math.ceil((String(r.t || '…').length + String(r.lab || r.qlab || '').length + 3) / per)); });
