    const f = frame.current; const d = f && f.contentDocument;
    if (!d) return null;
    const r = f.getBoundingClientRect(); const k = r.width / (f.offsetWidth || 1);
    const el = d.elementFromPoint((e.clientX - r.left) / k, (e.clientY - r.top) / k);
